const input = $json.body ?? $json;
const contentId = String(input.contentId ?? '').trim();
const locationId = String(input.locationId ?? '').trim();
const userId = String(input.userId ?? '').trim();
const accountIds = Array.isArray(input.accountIds) ? input.accountIds.map(String).map(v => v.trim()).filter(Boolean) : [];
const draft = String(input.draft ?? '').trim();
if (!contentId) throw new Error('contentId is required');
if (!locationId) throw new Error('locationId is required');
if (!userId) throw new Error('userId is required');
if (!accountIds.length) throw new Error('At least one GHL account ID is required');
if (!draft) throw new Error('Approved draft is required');
return [{ json: { contentId, locationId, userId, accountIds, summary: draft, type: 'post', status: 'published', approvedAt: new Date().toISOString() } }];

const request = $('Validate Publish Request').item.json;
const response = $json;
const post = response.results?.post;
if (!response.success || !post?._id) throw new Error(response.message || 'GoHighLevel did not return a post ID');
return [{ json: { contentId: request.contentId, status: post.status === 'published' ? 'published' : post.status === 'scheduled' ? 'scheduled' : 'approved', externalId: post._id, publishedAt: post.status === 'published' ? new Date().toISOString() : null, message: response.message || 'Content sent to GoHighLevel successfully.' } }];
